import{_ as d,o as r,c as a,aA as l}from"./chunks/framework.BMzE2Z9R.js";const u=JSON.parse('{"title":"第五届中国通用人工智能年会","description":"","frontmatter":{"comments":true},"headers":[],"relativePath":"conference/2020.md","filePath":"conference/2020.md","lastUpdated":1778415461000}'),e={name:"conference/2020.md"};function i(o,t,n,h,s,c){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="第五届中国通用人工智能年会" tabindex="-1">第五届中国通用人工智能年会 <a class="header-anchor" href="#第五届中国通用人工智能年会" aria-label="Permalink to &quot;第五届中国通用人工智能年会&quot;">​</a></h1><p><strong>时间地点</strong>：2020年12月12-13日，线上召开</p><h2 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>来源</th><th>报告人</th><th>报告标题</th></tr></thead><tbody><tr><td>1</td><td>—</td><td>王培</td><td>NARS速览（总览）</td></tr><tr><td>2</td><td>—</td><td>王涛、那迪</td><td>NARS速览（逻辑部分）</td></tr><tr><td>3</td><td>—</td><td>冯博杰</td><td>NARS速览（控制部分）</td></tr><tr><td>4</td><td>—</td><td>—</td><td>Demo Show</td></tr><tr><td>5</td><td>—</td><td>主持人：刘凯</td><td>互动圆桌</td></tr><tr><td>6</td><td>—</td><td>徐英瑾</td><td>如何让通用人工智能系统学会识数</td></tr><tr><td>7</td><td>—</td><td>冯博杰</td><td>AGI评价问题简述</td></tr><tr><td>8</td><td>—</td><td>张俊杰</td><td>NARS的线程竞争</td></tr><tr><td>9</td><td>—</td><td>那迪</td><td>以知识和资源相对不足为前提的决策模型</td></tr><tr><td>10</td><td>—</td><td>主持人：那迪</td><td>交流圆桌（短报告）</td></tr><tr><td>11</td><td>—</td><td>王傲楠、刘凯</td><td>何为&quot;常识&quot;？——拨开机器婴儿教育起点的迷雾</td></tr><tr><td>12</td><td>—</td><td>刘凯</td><td>通用人工智能系统经验结构的动态生长（一）——来自小学数学的证据</td></tr><tr><td>13</td><td>—</td><td>庞小萍、刘凯</td><td>通用人工智能系统经验结构的动态生长（二）——来自精神分裂症患者的证据</td></tr><tr><td>14</td><td>—</td><td>刘凯</td><td>人类婴儿启发下的机器教育新路径——机器感知运动的统合方案</td></tr><tr><td>15</td><td>—</td><td>朱菁、詹好</td><td>浅议AGI的定义和判定标准</td></tr><tr><td>16</td><td>—</td><td>马翰林</td><td>第二人称观点对于类人AI的意义——基于对仿真、模拟和模仿</td></tr><tr><td>17</td><td>—</td><td>黄彧</td><td>认知模式与智能体决策</td></tr><tr><td>18</td><td>—</td><td>刘锋</td><td>智能研究面临的三个困难</td></tr><tr><td>19</td><td>—</td><td>主持人：王培</td><td>合作圆桌</td></tr></tbody></table><h3 id="互动圆桌讨论议题" tabindex="-1">互动圆桌讨论议题 <a class="header-anchor" href="#互动圆桌讨论议题" aria-label="Permalink to &quot;互动圆桌讨论议题&quot;">​</a></h3><ul><li>AGI会变成超级智能，甚至毁灭人类吗？</li><li>图灵机是否意味着AGI注定无法实现？</li><li>AGI可以有真正的情感么？与情感计算有何区别？</li><li>AI一词更侧重机器学习和统计，如何从AI领域过渡到AGI？</li><li>为什么AGI研究已有多年，却至今很难看到落地应用？</li></ul><h3 id="交流圆桌短报告" tabindex="-1">交流圆桌短报告 <a class="header-anchor" href="#交流圆桌短报告" aria-label="Permalink to &quot;交流圆桌短报告&quot;">​</a></h3><ul><li>基于NARS的项目管理应用（王晨炜）</li><li>基于NARS的心理学研究探讨（黄英辉）</li><li>智视通用人工智能——打造最会聊天的聊天机器（智视科技）</li><li>AGI系统目标的自主性及必要性（徐博洋）</li><li>让机器睁开&quot;眼睛&quot;（孙常新）</li><li>与深度学习相比，为什么NARS更像生物（莫克陶）</li></ul><h3 id="合作圆桌讨论议题" tabindex="-1">合作圆桌讨论议题 <a class="header-anchor" href="#合作圆桌讨论议题" aria-label="Permalink to &quot;合作圆桌讨论议题&quot;">​</a></h3><p><strong>AGI回音壁：</strong></p><ul><li>当今人工智能技术瓶颈如何突破？</li><li>人工智能可解释性如何解决？</li><li>为什么人工智能需要小数据？</li><li>基于大数据人工智能局限性是什么？</li><li>为什么深度学习无法突破现有的人工智能瓶颈？</li><li>通用人工智能技术能够解决哪些企业痛点？</li><li>人工智能的正确发展路线是什么？</li><li>NARS框架下，是否只有类生物体才具备自发演化通用智能的可能性？</li><li>AIKR假设在NARS和AGI中有何重要作用？</li></ul><p><strong>NARS未来研究计划</strong></p><p><strong>合作及应用研究计划</strong></p>',13)])])}const _=d(e,[["render",i]]);export{u as __pageData,_ as default};
